import{_ as t,c as e,o as a,a4 as o}from"./chunks/framework.BYxathSa.js";const m=JSON.parse('{"title":"Q16：React 中的合成事件","description":"","frontmatter":{},"headers":[],"relativePath":"react/q16.md","filePath":"react/q16.md","lastUpdated":null}'),c={name:"react/q16.md"},r=o('<h1 id="q16-react-中的合成事件" tabindex="-1">Q16：React 中的合成事件 <a class="header-anchor" href="#q16-react-中的合成事件" aria-label="Permalink to &quot;Q16：React 中的合成事件&quot;">​</a></h1><p>React 封装了浏览器原生事件，形成<strong>合成事件（SyntheticEvent）</strong>。</p><ul><li><strong>目的</strong>：抹平不同浏览器的事件差异，提供一致的 API。</li><li><strong>原理</strong>：React 17 时代事件委托在 <code>document</code> 上，React 18 委托在根容器上。</li><li><strong>特点</strong>：使用驼峰命名（如 <code>onClick</code>），事件对象可复用（旧版需 <code>e.persist()</code>，18 后废弃）。</li><li><strong>与原生事件区别</strong>：阻止冒泡可使用 <code>e.stopPropagation()</code>，但阻止的是 React 事件冒泡；原生事件绑定在 DOM 上需注意执行顺序。</li></ul>',3),n=[r];function s(i,d,l,_,p,g){return a(),e("div",null,n)}const u=t(c,[["render",s]]);export{m as __pageData,u as default};
